    family: "Todi",
    rasConfidence: "High",
    rasEvidence: "tanarang 'deep; full of Bhakti and Karun ras'; Wikipedia 'a pensive, mournful mood'; Mathur 2015 sad then tensed; Parrikar 'every conceivable human emotion'; RG 'a plaintive raga'",
    variants: ["Gurjari Todi","Bilaskhani Todi","Bhupali Todi","Shuddha Todi","Bahaduri Todi","Ahiri Todi","Lachari Todi","Anjani Todi","Khat Todi","Bairagi Todi","Salagavarali"],
